param([Parameter(Mandatory)][string]$Owner,[Parameter(Mandatory)][string]$Repository,[Parameter(Mandatory)][string]$Branch,
    [Parameter(Mandatory)][string]$CommitSha,[string]$RequiredCheckName='server-baseline',[string]$TokenEnvironmentVariable='GITHUB_TOKEN',
    [Parameter(Mandatory)][string]$ObserverPrivateKeyFile,[Parameter(Mandatory)][string]$ObserverKeyId,
    [Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[Parameter(Mandatory)][string]$OutputDirectory)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";. "$PSScriptRoot/GitHubGovernance.Common.ps1"
if($Owner-notmatch'^[A-Za-z0-9_.-]+$'-or$Repository-notmatch'^[A-Za-z0-9_.-]+$'-or$Branch-notmatch'^[A-Za-z0-9._/-]+$'-or$CommitSha-notmatch'^[a-f0-9]{40}$'){throw 'GitHub target is invalid'}
$token=[Environment]::GetEnvironmentVariable($TokenEnvironmentVariable);if([string]::IsNullOrWhiteSpace($token)){throw "$TokenEnvironmentVariable is required with read access to repository metadata, checks and branch protection"}
$observer=Get-BackupKeyFingerprint $ObserverPrivateKeyFile 'GitHub governance observer' $true;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false;if($observer-ceq$release){throw 'GitHub observer and release signer must be separated'}
$headers=@{Accept='application/vnd.github+json';Authorization="Bearer $token";'X-GitHub-Api-Version'='2022-11-28';'User-Agent'='ET-ServerOps-Governance'};$base="https://api.github.com/repos/$Owner/$Repository"
$head=Invoke-RestMethod -Headers $headers -Uri "$base/branches/$([Uri]::EscapeDataString($Branch))";$protection=Invoke-RestMethod -Headers $headers -Uri "$base/branches/$([Uri]::EscapeDataString($Branch))/protection";$runs=Invoke-RestMethod -Headers $headers -Uri "$base/commits/$CommitSha/check-runs?per_page=100"
$required=@($protection.required_status_checks.contexts)+@($protection.required_status_checks.checks|ForEach-Object context)|Select-Object -Unique
$matched=@($runs.check_runs|Where-Object {$_.name-ceq$RequiredCheckName-and$_.head_sha-ceq$CommitSha-and$_.status-ceq'completed'-and$_.conclusion-ceq'success'}|Sort-Object completed_at -Descending|Select-Object -First 1)
if($matched.Count-ne1){throw 'A successful required hosted check was not found for the exact commit'};$run=$matched[0];$now=[DateTimeOffset]::UtcNow
$evidence=[ordered]@{SchemaVersion=1;Product='ET.Server';ArtifactType='GitHubProductionGovernance';TestOnly=$false;Owner=$Owner;Repository=$Repository;Branch=$Branch;CommitSha=$CommitSha;BranchHeadSha=[string]$head.commit.sha;RequiredCheckName=$RequiredCheckName;ObservedAtUtc=$now.ToString('O');ValidUntilUtc=$now.AddHours(1).ToString('O');ObserverKeyId=$ObserverKeyId;ObserverPublicKeySha256=$observer;ReleaseSigningPublicKeySha256=$release;
    BranchProtection=[ordered]@{RequiredStatusChecksStrict=[bool]$protection.required_status_checks.strict;RequiredChecks=@($required);EnforceAdmins=[bool]$protection.enforce_admins.enabled;RequiredApprovingReviewCount=[int]$protection.required_pull_request_reviews.required_approving_review_count;DismissStaleReviews=[bool]$protection.required_pull_request_reviews.dismiss_stale_reviews;RequireCodeOwnerReviews=[bool]$protection.required_pull_request_reviews.require_code_owner_reviews;RequireLastPushApproval=[bool]$protection.required_pull_request_reviews.require_last_push_approval;RequireConversationResolution=[bool]$protection.required_conversation_resolution.enabled;AllowForcePushes=[bool]$protection.allow_force_pushes.enabled;AllowDeletions=[bool]$protection.allow_deletions.enabled};HostedCheck=[ordered]@{Name=[string]$run.name;HeadSha=[string]$run.head_sha;Status=[string]$run.status;Conclusion=[string]$run.conclusion;CheckRunId=[long]$run.id;CompletedAtUtc=[string]$run.completed_at;HtmlUrl=[string]$run.html_url}}
Assert-GitHubProductionGovernance $evidence $now $false;$output=Assert-BackupPathOutsideRepository $OutputDirectory 'OutputDirectory';New-Item -ItemType Directory $output -Force|Out-Null;$file=Join-Path $output "$CommitSha.github-governance.json";if((Test-Path $file)-or(Test-Path "$file.observer.sig")){throw 'GitHub governance evidence already exists'};$bytes=$script:GitHubGovernanceUtf8.GetBytes(($evidence|ConvertTo-Json -Depth 10));try{[IO.File]::WriteAllBytes($file,$bytes);[IO.File]::WriteAllBytes("$file.observer.sig",(New-BackupSignature $bytes $ObserverPrivateKeyFile 'GitHub governance observer'));[ordered]@{Passed=$true;EvidenceFile=$file;CommitSha=$CommitSha;CheckRunId=[long]$run.id;EvidenceSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json}catch{foreach($path in @($file,"$file.observer.sig")){if(Test-Path $path){Remove-Item $path -Force}};throw}
